<script setup lang="ts">
import {computed,nextTick,ref} from 'vue';
import {useProject} from './store';
import {websites,newWebsite,switchWebsite} from './websites';
import type {Website} from './model';
const store=useProject(),emit=defineEmits<{edit:[id:string,importExisting?:boolean]}>();
defineProps<{editor:boolean}>();
const data=computed(()=>websites(store.project)),dialog=ref<HTMLDialogElement>(),draft=ref<Website>(),error=ref(''),saving=ref(false),method=ref('architecture');
const isNew=computed(()=>!data.value.items.some(s=>s.id===draft.value?.id));
async function open(site?:Website){draft.value=site?JSON.parse(JSON.stringify(site)):newWebsite(store.project);method.value='architecture';error.value='';await nextTick();dialog.value?.showModal();}
function copyCompany(){if(!draft.value)return;draft.value.profileMode='independent';draft.value.profile=JSON.parse(JSON.stringify(store.project.company));}
async function save(){if(!draft.value)return;saving.value=true;error.value='';const before=JSON.stringify(store.project);try{const created=isNew.value,site=JSON.parse(JSON.stringify(draft.value)) as Website;site.domain=site.domain.trim().toLowerCase();site.name=site.name.trim();if(site.profileMode==='shared')site.profile=null;const i=data.value.items.findIndex(s=>s.id===site.id);if(i<0)data.value.items.push(site);else data.value.items[i]=site;if(!data.value.activeId||created)switchWebsite(store.project,site.id);store.changed();await store.flush();dialog.value?.close();if(created)emit('edit',site.id,method.value==='import');}catch(e){store.project=JSON.parse(before);error.value=e instanceof Error?e.message:String(e);}finally{saving.value=false;}}
defineExpose({open});
</script>
<template>
 <section v-if="!editor" class="card"><div class="between"><h2>独立网站</h2><button class="primary" @click="open()">新建网站</button></div><div class="biz-cards"><article v-for="site in data.items" :key="site.id" class="biz-tile" :data-business-site="site.id"><div class="between"><h3>{{site.name}}</h3><span v-if="site.id===data.activeId" class="tag green">当前网站</span></div><p class="biz-domain">{{site.domain||'域名待设置'}}</p><p>{{site.profileMode==='shared'?store.project.company.product:site.profile?.product}}</p><div class="tags"><span class="tag">{{site.profileMode==='shared'?'共用公司资料':'独立公司资料'}}</span><span class="tag">{{site.id===data.activeId?store.project.pages.length:site.document.pages.length}} 个内容区块</span></div><p class="muted">{{site.profileMode==='shared'?store.project.company.name:site.profile?.name}}</p><div class="actions"><button @click="open(site)">网站设置</button><button class="primary" @click="emit('edit',site.id)">编辑网站</button></div></article></div><p v-if="!data.items.length" class="muted">暂无网站，点击“新建网站”开始。</p></section>
 <dialog ref="dialog" class="biz-dialog website-settings" @cancel="!saving&&dialog?.close()"><template v-if="draft"><div class="between"><h2>{{isNew?'新建网站':'网站设置'}}</h2><button type="button" :disabled="saving" @click="dialog?.close()">关闭</button></div><form @submit.prevent="save"><div class="form-grid"><label>网站名称<input v-model="draft.name" required maxlength="180"></label><label>网站域名<input v-model="draft.domain" placeholder="www.example.com" pattern="[a-zA-Z0-9.-]+" maxlength="253"></label><label>公司资料<select v-model="draft.profileMode" @change="draft.profileMode==='independent'&&!draft.profile&&copyCompany()"><option value="shared">共用公司资料</option><option value="independent">独立填写</option></select></label><div class="copy-company"><button type="button" @click="copyCompany">复制公共资料后独立修改</button></div></div><div v-if="draft.profileMode==='independent'&&draft.profile" class="independent-profile"><div class="form-grid"><label>公司 / 品牌名称<input v-model="draft.profile.name" required maxlength="180"></label><label>主要产品<input v-model="draft.profile.product" maxlength="1000"></label></div><div class="profile-columns"><label>公司介绍<textarea v-model="draft.profile.description" rows="3"></textarea></label><label>强项<textarea v-model="draft.profile.strength" rows="3"></textarea></label><label>业务范围与限制<textarea v-model="draft.profile.excluded" rows="3"></textarea></label></div></div><fieldset v-if="isNew" class="creation-method"><legend>建站方式</legend><label><input v-model="method" type="radio" value="architecture">选取网站架构</label><label><input v-model="method" type="radio" value="import">从已有网站读取</label></fieldset><p v-if="error" role="alert" class="error">{{error}}</p><div class="card-actions"><button class="primary" :disabled="saving">{{saving?'正在保存…':isNew?'创建并继续':'保存'}}</button></div></form></template></dialog>
</template>
